// Authored from grouped SELECT/HAVING scope, not generated by the lowerer.
// ID 3 has two contributions, ID 0 is excluded, and amount retains NULL.
const rows = [{id: 3, amount: 30}, {id: 1, amount: null},
  {id: 2, amount: 20}, {id: 3, amount: 30}, {id: 0, amount: 99}];
const number = (name, nullable = false) => ({name,
  contract: {type: 'number', nullable}});
const nextColumns = [number('next'), number('n')];
const nextRows = [{next: 3, n: 1}, {next: 4, n: 2}];
const program = {version: 'actql/0.1', id: 'fixture.having_projection',
  stages: [{id: 'capture', inputs: {remote: {connector: 'crm/main', resource: 'r'}},
    steps: [{from: 'remote', filter: {gt: [{field: 'id'}, {literal: 0}]}},
      {select: ['amount', 'id'], as: 'captured'}],
    results: {source: {from: 'captured', fields: ['amount', 'id']}}},
  {id: 'main', inputs: {records: {result: {stage: 'capture', result: 'source'}}},
    steps: [{from: 'records', group: {by: ['id'], aggregates: {n: {fn: 'count'}}}},
      {derive: {next: {add: [{field: 'id'}, {literal: 1}]}}},
      {filter: {gt: [{field: 'next'}, {literal: 2}]}},
      {select: ['next', 'n']},
      {sort: [{field: 'next', dir: 'asc', nulls: 'first'}], as: 'summary'}],
    results: {rows: {from: 'summary', fields: ['next', 'n']}}}],
  results: {answer: {from: {stage: 'main', result: 'rows'}}}};
const source = 'SELECT records.id + 1 AS next, COUNT(*) AS n FROM records '
  + 'WHERE id > 0 GROUP BY id HAVING `NeXt` > 2 ORDER BY next';
const success = (name, format, text, overrides = {}) => ({
  name: 'having-projection-' + name, format, text, sourceRows: rows,
  expected: nextRows, columns: nextColumns, sourceReadSessionCount: 1,
  ...overrides,
});
export const havingProjectionSuccesses = [
  success('independent-json-control', 'json', JSON.stringify(program)),
  success('computed-alias', 'sql', source),
  // Substituting input ID in HAVING would discard every row; -ID is the alias.
  success('alias-over-input', 'sql', 'SELECT -id AS id, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY records.id HAVING id < -1 ORDER BY id', {
    expected: [{id: -3, n: 2}, {id: -2, n: 1}],
    columns: [number('id'), number('n')],
  }),
  // Substituting the alias for qualified records.id would incorrectly keep 3.
  success('qualified-grouped-input', 'sql', 'SELECT -id AS id, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY records.id HAVING records.id < 3 ORDER BY id', {
    expected: [{id: -2, n: 1}, {id: -1, n: 1}],
    columns: [number('id'), number('n')],
  }),
  success('shared-projection-slot', 'sql', 'SELECT id + 1 AS next, id + 1 AS also, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY id HAVING next > 2 AND also < 4 ORDER BY next', {
    expected: [{next: 3, also: 3, n: 1}],
    columns: [number('next'), number('also'), number('n')],
  }),
  success('nullable-input', 'sql', 'SELECT amount + 1 AS next, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY amount HAVING next > 20 ORDER BY next', {
    expected: [{next: 21, n: 1}, {next: 31, n: 2}],
    columns: [number('next', true), number('n')],
  }),
  success('empty-input', 'sql', source, {sourceRows: [], expected: []}),
  success('scoped-join', 'sql', 'WITH a AS (SELECT id FROM records), b AS (SELECT 1 AS k), c AS (SELECT 1 AS z) SELECT r.id + 1 AS next, COUNT(*) AS n FROM a AS r JOIN b ON r.id = b.k JOIN c ON b.k = c.z GROUP BY r.id HAVING next > 1 ORDER BY next', {
    expected: [{next: 2, n: 1}],
  }),
  success('next-pipe-scope', 'aql-text', 'SELECT id + 1 AS id, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY records.id HAVING id > 2 |> SELECT id + 1 AS next, n |> ORDER BY next', {
    expected: [{next: 4, n: 1}, {next: 5, n: 2}],
  }),
  success('declared-parameters', 'sql', 'SELECT id + @increment AS next, COUNT(*) AS n FROM records WHERE id > 0 GROUP BY id HAVING next > @minimum ORDER BY next', {
    parameterDeclarations: {increment: {type: 'number'}, minimum: {type: 'number'}},
    parameters: {increment: 2, minimum: 3},
    expected: [{next: 4, n: 1}, {next: 5, n: 2}],
  }),
];
export const havingProjectionRefusals = [
  'SELECT amount + 1 AS next, COUNT(*) AS n FROM records GROUP BY id HAVING next > 0',
  'SELECT id + 1 AS next, next + 1 AS sibling, COUNT(*) AS n FROM records GROUP BY id HAVING next > 0',
  'SELECT id + 1 AS next, COUNT(*) AS n FROM records GROUP BY id HAVING records.next > 0',
  'SELECT id + 1 AS next, id + 2 AS next, COUNT(*) AS n FROM records GROUP BY id HAVING next > 0',
].map((text, index) => ({name: 'having-projection-invalid-scope-' + index,
  format: 'sql', text}));
